  var context=new DefaultCaseContext(run,TargetRole.IDP,Clock.systemUTC(),TestPlan.Parameters.defaults(),TestPlan.Interaction.defaults(),Reachability.CONFIRMED,recorder,true);
  var test=new TransientAllowCreateScenarioTestCase(r->{throw new AssertionError("Owned proof consulted active configuration");},r->r.equals(run)?Optional.of(key):Optional.empty()).withNativeEvidence(directory,e->bodies.get(e.id()),r->target);
  require(test.start(context).equals(new com.samlscope.core.caseexec.CaseStep.Finish(expected)));for(var event:List.of(new com.samlscope.core.caseexec.CaseEvent.TranscriptReady(),new com.samlscope.core.caseexec.CaseEvent.ConfigConfirmed(),new com.samlscope.core.caseexec.CaseEvent.Aborted("cancelled"),new com.samlscope.core.caseexec.CaseEvent.TimedOut(Duration.ZERO)))require(test.resume(context,com.samlscope.core.caseexec.CaseState.initial(),event).equals(new com.samlscope.core.caseexec.CaseStep.Finish(expected)));
